-- Brands -------------------------------------------------------------
INSERT INTO public.brands (name, slug, description, sort_order, is_active)
VALUES
  ('Besjaar', 'besjaar', 'Het eigen merk van de winkel. Besjaar staat voor praktische producten voor huis, badkamer, tuin en onderweg — verlichting, douchecomfort en handige huishoudelijke artikelen.', 1, true),
  ('RYNEX', 'rynex', 'RYNEX levert accessoires voor werkplek, keuken, auto en fiets: telefoonhouders, adapters, kaartlezers, weegschalen en hobbymateriaal.', 2, true),
  ('LYNEX', 'lynex', 'LYNEX richt zich op persoonlijke verzorging, met airstylers en warmteborstels voor het stylen van haar.', 3, true)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  sort_order = EXCLUDED.sort_order,
  is_active = true;

